    public static void reserveCart(MobCartID _cartId, MobDocumentDeviceId _device, userId _user)
    {
        MobReservedCarts resCart;
        ttsbegin;
        delete_from resCart
            where	resCart.CartID == _cartId;

		resCart.CartID = _cartId;
        resCart.DeviceId = _device;
        resCart.UserId = _user;
        resCart.insert();
        ttscommit;
    }

public static void unreserveCart(MobCartID _cartId)
{
    MobReservedCarts	resCart;
    MobCarts			cart;
    ttsbegin;
    delete_from resCart
        where	resCart.CartID == _cartId;

    cart = MobCarts::Find(_cartId,true);
    cart.PickMode = NoYes::Yes;
    //cart.ReferenceId = '';
    cart.update();

    ttscommit;
}

    public static str reserveInfo(MobCartID _cartId)
    {
        MobReservedCarts resCart;
        select firstonly resCart where resCart.CartID == _cartId;

		if (!resCart)
        {
            return '';
        }

        return "@MobileWMS:CartCurrentlyUsedBy" + (resCart.UserId ? HcmWorker::find(HcmWorker::userId2Worker(resCart.UserId)).name() : '') + (resCart.UserId && resCart.DeviceId ? ', ' :'') + (resCart.DeviceId ? "@SYS90307" + ' ' + TFMDeviceTable::FindOrCreateDevice(resCart.DeviceId).Name : '');

    }

    public static boolean IsCartReserved(MobCartID _cartId, MobDocumentDeviceId _device, userId _user)
    {
        MobReservedCarts resCart;
        select firstonly resCart where resCart.CartID == _cartId;

		if (!resCart.recid)
        {
            return false;
        }
		if ((!_device || resCart.DeviceId != _device) && (!_user || resCart.UserId != _user))
        {
            return true;
        }

        return false;
    }
